def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    pts={v:[] for v in range(10)}
    for r in range(h):
        for c in range(w):
            if grid[r][c]: pts[grid[r][c]].append((r,c))
    def line(r,c,rr,cc,color=5):
        dr=0 if rr==r else (1 if rr>r else -1)
        dc=0 if cc==c else (1 if cc>c else -1)
        while (r,c)!=(rr,cc):
            r+=dr;c+=dc
            if out[r][c]==0:out[r][c]=color
    # Each pair of markers makes a cross with a colored pivot and reflected arms.
    if pts[1] and pts[2]:
        r,c=pts[1][0];a,b=pts[2][0]
        # pair's center is the coordinatewise midpoint, arms lie on its row/column
        cr=(r+a)//2; cc=(c+b)//2
        if (r+a)%2==0 and (c+b)%2==0:
            for j in range(min(c,b),max(c,b)+1):
                if out[cr][j]==0:out[cr][j]=5
            for i in range(min(r,a),max(r,a)+1):
                if out[i][cc]==0:out[i][cc]=5
    if pts[3] and pts[6]:
        (r,c),(a,b)=pts[6][0],pts[3][0]
        # extend along their shared row as an arm
