def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    points = {v: [] for v in range(10)}
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                points[grid[r][c]].append((r, c))

    # The examples establish these translations for each color.
    shifts = {1: (-1, 2), 2: (0, -4), 3: (3, 0), 6: (-6, 0)}
    paths = {}
    for color, delta in shifts.items():
        for r, c in points[color]:
            dr, dc = delta
            end = (r + dr, c + dc)
            if not (0 <= end[0] < h and 0 <= end[1] < w):
                continue
            paths[color] = (r, c, end[0], end[1])
            steps = max(abs(dr), abs(dc))
            sr = (dr > 0) - (dr < 0)
            sc = (dc > 0) - (dc < 0)
            for k in range(1, steps):
                rr, cc = r + sr*k, c + sc*k
                if out[rr][cc] == 0:
                    out[rr][cc] = 5
            if out[end[0]][end[1]] == 0:
                out[end[0]][end[1]] = color

    # When a horizontal 2 path meets a vertical 3/6 path, mark the crossing
    # and continue a diagonal 4 ray down-left, as in the demonstrations.
    if 2 in paths:
        r2, c2, er2, ec2 = paths[2]
        for color in (3, 6):
            if color not in paths:
                continue
            r, c, er, ec = paths[color]
            if c2 != c or not (min(r, er) <= r2 <= max(r, er)):
                continue
            if not (min(c2, ec2) <= c <= max(c2, ec2)):
                continue
            out[r2][c] = 4
            k = 1
            while r2+k < h and c-k >= 0:
                out[r2+k][c-k] = 4
                k += 1
    return out
